DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.flight_quote(uuid,text)'::regprocedure) INTO definition; definition:=replace(definition,'IF (t.fuel_type=''100LL'' AND a.fuel_100ll_available=false) OR (t.fuel_type=''Jet-A'' AND a.fuel_jeta_available=false) THEN RAISE EXCEPTION ''Required fuel unavailable at origin''; END IF;',''); definition:=replace(definition,'fuel:=mins/60*t.fuel_burn_gph;','fuel:=mins/60*t.fuel_burn_gph; IF public.airport_fuel_stock(a.icao,t.fuel_type)<fuel THEN RAISE EXCEPTION ''Insufficient airport fuel stock''; END IF;'); EXECUTE definition; END $$;